270	        // Backfill the existing members so the whole household carries one shared id.
271	        householdMembers(owner.getLastName(), owner.getAddress()).stream()
272	            .filter(member -> !householdId.equals(member.getHouseholdId()))
273	            .forEach(member -> {
274	                member.setHouseholdId(householdId);
275	                ownerRepository.save(member);
276	            });
277	        owner.setHouseholdId(householdId);
278	        return householdId;
